package main

import (
	"bufio"
	"fmt"
	"os"
)

func isPrime(number int) bool {
	if number <= 1 {
		return false
	}
	for i := 2; i < number; i++ {
		if number%i == 0 {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n, m int
	fmt.Fscan(in, &n, &m)

	for i := n + 1; i <= m; i++ {
		if isPrime(i) && i != m {
			fmt.Println("NO")
			return
		}
		if isPrime(i) && i == m {
			fmt.Println("YES")
			return
		}
	}

	fmt.Println("NO")
}

